def model(dbt, session):
    dbt.config(materialized="incremental", unique_key="rating_id")

    ratings = dbt.ref("stg_ridenow__ratings").df()

    if dbt.is_incremental:
        max_rated_at = session.sql(
            f"select max(rated_at) from {dbt.this}"
        ).fetchone()[0]
        ratings = ratings[ratings["rated_at"] > max_rated_at]

    return ratings

